-- LESSON 21: Tiere
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000015',1,'APPROVED','PUBLISHED',
'{"objectives":["Name common animals","Say what animals you like","Use mögen with animals"],"explanation":{"intro":"Animals are a great vocabulary topic. Germans love their pets — Germany has one of the highest pet ownership rates in Europe.","culturalNote":"Der Hund (dog) is the most popular pet in Germany, followed by die Katze (cat)."},"examples":[{"german":"Ich mag Hunde.","english":"I like dogs."},{"german":"Der Hund ist groß.","english":"The dog is big."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name common animals and say which ones I like."}}',
'{"items":[{"word":"der Hund","translation":"dog","pronunciation":"dayr HOONT","example":"Mein Hund heißt Max."},{"word":"die Katze","translation":"cat","pronunciation":"dee KAT-seh","example":"Die Katze schläft."},{"word":"der Vogel","translation":"bird","pronunciation":"dayr FOH-gel","example":"Der Vogel singt."},{"word":"das Pferd","translation":"horse","pronunciation":"dahs PFAYRT","example":"Das Pferd ist schnell."},{"word":"der Fisch","translation":"fish","pronunciation":"dayr FISH","example":"Ich habe einen Fisch."},{"word":"das Kaninchen","translation":"rabbit","pronunciation":"dahs kah-NEEN-khen","example":"Das Kaninchen ist weiß."}]}',
'{"title":"Mögen — to like","pattern":"ich mag / du magst / er mag","explanation":"Mögen is used to express liking something. It is irregular: ich mag, du magst, er/sie/es mag. It is very common with food, animals, and activities.","examples":[{"sentence":"Ich mag Katzen.","translation":"I like cats."},{"sentence":"Magst du Hunde?","translation":"Do you like dogs?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"What does ''der Hund'' mean?","options":["dog","cat","bird","fish"],"correctAnswer":"dog"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like cats.","options":["Ich mag Katzen.","Ich mag Hunde.","Die Katze ist groß.","Magst du Tiere?"],"correctAnswer":"Ich mag Katzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Vogel ___ schön.","options":["ist","hat","mag","gibt"],"correctAnswer":"ist"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My dog is called Max","wordBankItems":["Mein","Hund","heißt","Max","."],"correctAnswer":"Mein Hund heißt Max ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Kaninchen'' means?","options":["rabbit","horse","fish","cat"],"correctAnswer":"rabbit"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 22: Die Schule
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000016',1,'APPROVED','PUBLISHED',
'{"objectives":["Name school subjects","Talk about your school day","Use haben for schedules"],"explanation":{"intro":"School vocabulary is essential for students and anyone talking about education. The German school system has several levels including Grundschule and Gymnasium.","culturalNote":"In Germany, school typically starts at 8am and ends around 1pm. Afternoon activities are optional."},"examples":[{"german":"Ich habe heute Mathematik.","english":"I have maths today."},{"german":"Mein Lieblingsfach ist Deutsch.","english":"My favourite subject is German."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name school subjects and talk about my timetable."}}',
'{"items":[{"word":"die Schule","translation":"school","pronunciation":"dee SHOO-leh","example":"Ich gehe zur Schule."},{"word":"das Fach","translation":"subject","pronunciation":"dahs FAKH","example":"Welches Fach magst du?"},{"word":"Mathematik","translation":"mathematics","pronunciation":"mah-teh-mah-TEEK","example":"Mathematik ist schwer."},{"word":"Deutsch","translation":"German (subject)","pronunciation":"DOYCH","example":"Ich lerne Deutsch."},{"word":"der Lehrer","translation":"teacher (m)","pronunciation":"dayr LAY-rer","example":"Der Lehrer erklärt."},{"word":"das Heft","translation":"notebook","pronunciation":"dahs HEFT","example":"Schreib ins Heft."}]}',
'{"title":"Haben — to have (schedules)","pattern":"ich habe / du hast / er hat + subject","explanation":"Use haben to talk about what lessons you have. The timetable construction is: Ich habe + subject + day/time. Heute = today, morgen = tomorrow.","examples":[{"sentence":"Ich habe heute Sport.","translation":"I have PE today."},{"sentence":"Wir haben morgen Englisch.","translation":"We have English tomorrow."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Fach'' means?","options":["subject","school","notebook","teacher"],"correctAnswer":"subject"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My favourite subject is German.","options":["Mein Lieblingsfach ist Deutsch.","Ich habe Mathematik.","Der Lehrer ist gut.","Ich gehe zur Schule."],"correctAnswer":"Mein Lieblingsfach ist Deutsch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ heute Mathematik.","options":["habe","bin","gehe","mag"],"correctAnswer":"habe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We have English tomorrow","wordBankItems":["Wir","haben","morgen","Englisch","."],"correctAnswer":"Wir haben morgen Englisch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Lehrer'' means?","options":["teacher","student","subject","school"],"correctAnswer":"teacher"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 23: Sport treiben
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000017',1,'APPROVED','PUBLISHED',
'{"objectives":["Name popular sports","Say which sport you play","Use spielen and treiben"],"explanation":{"intro":"Sport is a big part of German life. Football, tennis, and cycling are all hugely popular.","culturalNote":"Germany hosted the FIFA World Cup in 2006 and won it in 2014. Fußball is a national passion."},"examples":[{"german":"Ich spiele Fußball.","english":"I play football."},{"german":"Sie treibt gern Sport.","english":"She likes doing sport."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name sports and say which ones I play."}}',
'{"items":[{"word":"der Fußball","translation":"football/soccer","pronunciation":"dayr FOOS-bal","example":"Ich spiele Fußball."},{"word":"Tennis spielen","translation":"to play tennis","pronunciation":"TEN-is SHPEE-len","example":"Er spielt Tennis."},{"word":"schwimmen","translation":"to swim","pronunciation":"SHVIM-en","example":"Sie schwimmt gern."},{"word":"laufen","translation":"to run","pronunciation":"LOW-fen","example":"Ich laufe jeden Tag."},{"word":"der Sport","translation":"sport/PE","pronunciation":"dayr SHPORT","example":"Sport ist gesund."},{"word":"das Stadion","translation":"stadium","pronunciation":"dahs SHTAH-dee-on","example":"Das Stadion ist voll."}]}',
'{"title":"Spielen vs. treiben for sport","pattern":"spielen + ball sport / Sport treiben = to do sport generally","explanation":"Use spielen for sports played with a ball or opponent: Fußball spielen, Tennis spielen. Use Sport treiben for sport generally. Schwimmen, laufen, radfahren stand alone as verbs.","examples":[{"sentence":"Ich spiele Basketball.","translation":"I play basketball."},{"sentence":"Wir treiben Sport.","translation":"We do sport."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"How do you say ''I play football''?","options":["Ich spiele Fußball.","Ich treibe Sport.","Ich laufe gern.","Fußball ist gut."],"correctAnswer":"Ich spiele Fußball."},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"She likes swimming.","options":["Sie schwimmt gern.","Er spielt Tennis.","Ich laufe schnell.","Das Stadion ist groß."],"correctAnswer":"Sie schwimmt gern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ jeden Tag.","options":["laufe","spiele","treibe","schwimme"],"correctAnswer":"laufe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Sport is healthy","wordBankItems":["Sport","ist","gesund","."],"correctAnswer":"Sport ist gesund ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Stadion'' means?","options":["stadium","sport","ball","team"],"correctAnswer":"stadium"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 24: Musik hören
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000018',1,'APPROVED','PUBLISHED',
'{"objectives":["Name musical instruments","Talk about music preferences","Use spielen for instruments"],"explanation":{"intro":"Music is universal. Learn how to talk about music genres and instruments in German.","culturalNote":"Germany has a rich classical music heritage — Bach, Beethoven, and Brahms are all German. Berlin also has a famous techno club scene."},"examples":[{"german":"Ich spiele Gitarre.","english":"I play guitar."},{"german":"Ich höre gern Popmusik.","english":"I like listening to pop music."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about music and name instruments I play."}}',
'{"items":[{"word":"die Gitarre","translation":"guitar","pronunciation":"dee gee-TAR-reh","example":"Ich spiele Gitarre."},{"word":"das Klavier","translation":"piano","pronunciation":"dahs klah-VEER","example":"Sie spielt Klavier."},{"word":"die Geige","translation":"violin","pronunciation":"dee GY-geh","example":"Er spielt Geige."},{"word":"die Musik","translation":"music","pronunciation":"dee moo-ZEEK","example":"Ich liebe Musik."},{"word":"das Lied","translation":"song","pronunciation":"dahs LEET","example":"Das Lied ist schön."},{"word":"der Sänger","translation":"singer (m)","pronunciation":"dayr ZEN-ger","example":"Der Sänger ist gut."}]}',
'{"title":"Spielen for instruments (no article)","pattern":"ich spiele + instrument (no article)","explanation":"When saying you play an instrument, do not use an article. Ich spiele Gitarre — not Ich spiele die Gitarre. This mirrors how German drops the article for professions (Ich bin Lehrer).","examples":[{"sentence":"Ich spiele Klavier.","translation":"I play piano."},{"sentence":"Spielst du ein Instrument?","translation":"Do you play an instrument?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Geige'' means?","options":["violin","guitar","piano","drum"],"correctAnswer":"violin"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like listening to music.","options":["Ich höre gern Musik.","Ich spiele Gitarre.","Das Lied ist schön.","Ich liebe Musik."],"correctAnswer":"Ich höre gern Musik."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich spiele ___.","options":["Klavier","das Klavier","ein Klavier","die Klavier"],"correctAnswer":"Klavier"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She plays violin","wordBankItems":["Sie","spielt","Geige","."],"correctAnswer":"Sie spielt Geige ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Lied'' means?","options":["song","music","singer","concert"],"correctAnswer":"song"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 25: Hausarbeit
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000019',1,'APPROVED','PUBLISHED',
'{"objectives":["Name household chores","Say what chores you do","Use müssen for obligations"],"explanation":{"intro":"Household chores vocabulary is practical for everyday life and describing your routine.","culturalNote":"In German households, Kehrwoche (sweeping week) is a tradition especially in Baden-Württemberg where residents take turns cleaning shared spaces."},"examples":[{"german":"Ich muss heute saugen.","english":"I must vacuum today."},{"german":"Wer wäscht ab?","english":"Who is washing up?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name household chores and say what I need to do."}}',
'{"items":[{"word":"saugen","translation":"to vacuum","pronunciation":"ZOW-gen","example":"Ich sauge das Wohnzimmer."},{"word":"spülen","translation":"to wash up","pronunciation":"SHPÜ-len","example":"Kannst du spülen?"},{"word":"kochen","translation":"to cook","pronunciation":"KOKH-en","example":"Ich koche heute Abend."},{"word":"waschen","translation":"to wash (laundry)","pronunciation":"VAH-shen","example":"Ich wasche die Wäsche."},{"word":"putzen","translation":"to clean","pronunciation":"POOT-sen","example":"Ich putze das Bad."},{"word":"aufräumen","translation":"to tidy up","pronunciation":"OWF-roy-men","example":"Räum dein Zimmer auf!"}]}',
'{"title":"Müssen — must/have to","pattern":"ich muss / du musst / er muss + infinitive at end","explanation":"Müssen expresses obligation or necessity. The infinitive goes to the end of the sentence. Ich muss saugen = I must vacuum. It is a modal verb — very common in daily life.","examples":[{"sentence":"Ich muss aufräumen.","translation":"I must tidy up."},{"sentence":"Sie muss kochen.","translation":"She has to cook."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Aufräumen'' means?","options":["to tidy up","to vacuum","to cook","to wash"],"correctAnswer":"to tidy up"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I must clean the bathroom.","options":["Ich muss das Bad putzen.","Ich koche heute.","Wer wäscht ab?","Ich sauge gern."],"correctAnswer":"Ich muss das Bad putzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ heute saugen.","options":["muss","kann","will","mag"],"correctAnswer":"muss"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Tidy up your room!","wordBankItems":["Räum","dein","Zimmer","auf","!"],"correctAnswer":"Räum dein Zimmer auf !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Spülen'' means?","options":["to wash up","to vacuum","to cook","to clean"],"correctAnswer":"to wash up"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 26: Gefühle
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-00000000001a',1,'APPROVED','PUBLISHED',
'{"objectives":["Express feelings and emotions","Ask how someone feels","Use sein + adjective for states"],"explanation":{"intro":"Expressing how you feel is essential for any conversation. German has rich vocabulary for emotions.","culturalNote":"Germans tend to be direct about how they feel. Wie geht es Ihnen? (formal) / Wie geht es dir? (informal) are standard greetings asking how you are."},"examples":[{"german":"Ich bin glücklich.","english":"I am happy."},{"german":"Wie geht es dir?","english":"How are you?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can express my feelings and ask how others are."}}',
'{"items":[{"word":"glücklich","translation":"happy","pronunciation":"GLÜK-likh","example":"Ich bin glücklich."},{"word":"traurig","translation":"sad","pronunciation":"TROW-rikh","example":"Er ist traurig."},{"word":"müde","translation":"tired","pronunciation":"MÜ-deh","example":"Ich bin sehr müde."},{"word":"nervös","translation":"nervous","pronunciation":"ner-VÖS","example":"Sie ist nervös."},{"word":"aufgeregt","translation":"excited","pronunciation":"OWF-geh-regt","example":"Ich bin aufgeregt."},{"word":"wütend","translation":"angry","pronunciation":"VÜ-tent","example":"Er ist wütend."}]}',
'{"title":"Sein + adjective for states","pattern":"ich bin + adjective","explanation":"Use sein (to be) with an adjective to describe emotional states. The adjective does not change after bin/bist/ist. Ich bin glücklich, du bist müde, er ist traurig.","examples":[{"sentence":"Ich bin sehr glücklich heute.","translation":"I am very happy today."},{"sentence":"Bist du müde?","translation":"Are you tired?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Traurig'' means?","options":["sad","happy","tired","angry"],"correctAnswer":"sad"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am very tired.","options":["Ich bin sehr müde.","Ich bin glücklich.","Er ist wütend.","Sie ist nervös."],"correctAnswer":"Ich bin sehr müde."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ aufgeregt.","options":["bin","habe","mag","gehe"],"correctAnswer":"bin"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: How are you?","wordBankItems":["Wie","geht","es","dir","?"],"correctAnswer":"Wie geht es dir ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wütend'' means?","options":["angry","nervous","excited","sad"],"correctAnswer":"angry"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 27: Die Jahreszeiten
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-00000000001b',1,'APPROVED','PUBLISHED',
'{"objectives":["Name the four seasons","Describe seasonal weather","Use im for seasons"],"explanation":{"intro":"Germany has four distinct seasons. Knowing season vocabulary lets you talk about weather, activities and plans.","culturalNote":"Germans eagerly await Sommer (summer) after long grey winters. Herbst (autumn) is famous for colourful forests and wine festivals."},"examples":[{"german":"Im Sommer ist es heiß.","english":"In summer it is hot."},{"german":"Ich mag den Frühling.","english":"I like spring."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name the seasons and describe seasonal weather."}}',
'{"items":[{"word":"der Frühling","translation":"spring","pronunciation":"dayr FRÜH-ling","example":"Im Frühling blühen Blumen."},{"word":"der Sommer","translation":"summer","pronunciation":"dayr ZOM-er","example":"Der Sommer ist heiß."},{"word":"der Herbst","translation":"autumn","pronunciation":"dayr HERPST","example":"Im Herbst fallen Blätter."},{"word":"der Winter","translation":"winter","pronunciation":"dayr VIN-ter","example":"Der Winter ist kalt."},{"word":"heiß","translation":"hot","pronunciation":"HYSS","example":"Es ist sehr heiß."},{"word":"die Blume","translation":"flower","pronunciation":"dee BLOO-meh","example":"Die Blume ist schön."}]}',
'{"title":"Im + season","pattern":"im + season name (dative contraction)","explanation":"Use im before all four seasons: im Frühling, im Sommer, im Herbst, im Winter. Im = in dem (dative). This is the same pattern as im Juli (in July).","examples":[{"sentence":"Im Winter schneit es.","translation":"In winter it snows."},{"sentence":"Im Frühling ist es warm.","translation":"In spring it is warm."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Herbst'' means?","options":["autumn","spring","summer","winter"],"correctAnswer":"autumn"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In winter it is cold.","options":["Im Winter ist es kalt.","Im Sommer ist es heiß.","Der Frühling ist schön.","Im Herbst regnet es."],"correctAnswer":"Im Winter ist es kalt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ Sommer ist es heiß.","options":["Im","Im","In","An"],"correctAnswer":"Im"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In spring flowers bloom","wordBankItems":["Im","Frühling","blühen","Blumen","."],"correctAnswer":"Im Frühling blühen Blumen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Blume'' means?","options":["flower","leaf","tree","grass"],"correctAnswer":"flower"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 28: Geburtstag feiern
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-00000000001c',1,'APPROVED','PUBLISHED',
'{"objectives":["Wish someone happy birthday","Talk about birthday plans","Use werden for age"],"explanation":{"intro":"Birthdays are important celebrations in Germany. Knowing birthday vocabulary lets you join in the festivities.","culturalNote":"In Germany, you should not wish someone happy birthday before their actual birthday — it is considered bad luck!"},"examples":[{"german":"Herzlichen Glückwunsch zum Geburtstag!","english":"Happy birthday!"},{"german":"Ich werde heute 30.","english":"I am turning 30 today."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can wish someone happy birthday and talk about age."}}',
'{"items":[{"word":"der Geburtstag","translation":"birthday","pronunciation":"dayr geh-BURTS-tahk","example":"Wann ist dein Geburtstag?"},{"word":"Herzlichen Glückwunsch","translation":"congratulations / happy birthday","pronunciation":"HERTS-likhen GLÜK-voonsh","example":"Herzlichen Glückwunsch!"},{"word":"das Geschenk","translation":"gift/present","pronunciation":"dahs geh-SHENK","example":"Das Geschenk ist toll."},{"word":"die Kerze","translation":"candle","pronunciation":"dee KER-tseh","example":"Blas die Kerzen aus!"},{"word":"die Torte","translation":"birthday cake","pronunciation":"dee TOR-teh","example":"Die Torte ist lecker."},{"word":"feiern","translation":"to celebrate","pronunciation":"FY-ern","example":"Wir feiern heute."}]}',
'{"title":"Werden — to turn (age)","pattern":"ich werde + number (age)","explanation":"Use werden to say you are turning a certain age. Ich werde 20 = I am turning 20. The number does not need Jahre alt after it in casual speech, though Ich werde 20 Jahre alt is also correct.","examples":[{"sentence":"Sie wird heute 25.","translation":"She is turning 25 today."},{"sentence":"Wann wirst du 18?","translation":"When do you turn 18?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"How do you say ''happy birthday''?","options":["Herzlichen Glückwunsch!","Guten Morgen!","Viel Spaß!","Auf Wiedersehen!"],"correctAnswer":"Herzlichen Glückwunsch!"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The present is great.","options":["Das Geschenk ist toll.","Die Torte ist lecker.","Wir feiern heute.","Blas die Kerzen aus!"],"correctAnswer":"Das Geschenk ist toll."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ heute 30.","options":["werde","bin","habe","feiere"],"correctAnswer":"werde"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are celebrating today","wordBankItems":["Wir","feiern","heute","."],"correctAnswer":"Wir feiern heute ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Torte'' means?","options":["birthday cake","candle","present","party"],"correctAnswer":"birthday cake"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 29: Technologie im Alltag
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-00000000001d',1,'APPROVED','PUBLISHED',
'{"objectives":["Name everyday technology","Talk about using devices","Use benutzen and schauen"],"explanation":{"intro":"Technology vocabulary is essential in the modern world. Learn to talk about phones, computers, and the internet in German.","culturalNote":"Germany is home to major tech events like the IFA consumer electronics show in Berlin every September."},"examples":[{"german":"Ich benutze mein Handy.","english":"I use my mobile phone."},{"german":"Schaust du YouTube?","english":"Do you watch YouTube?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about everyday technology and devices."}}',
'{"items":[{"word":"das Handy","translation":"mobile phone","pronunciation":"dahs HEN-dee","example":"Mein Handy ist neu."},{"word":"der Laptop","translation":"laptop","pronunciation":"dayr LAP-top","example":"Ich arbeite am Laptop."},{"word":"das Internet","translation":"internet","pronunciation":"dahs IN-ter-net","example":"Das Internet ist schnell."},{"word":"die App","translation":"app","pronunciation":"dee APP","example":"Diese App ist kostenlos."},{"word":"laden","translation":"to charge / to download","pronunciation":"LAH-den","example":"Ich lade mein Handy."},{"word":"schicken","translation":"to send","pronunciation":"SHIK-en","example":"Ich schicke eine Nachricht."}]}',
'{"title":"Trennbare Verben — separable verbs intro","pattern":"prefix splits off: herunterladen → ich lade herunter","explanation":"Some German verbs have separable prefixes that split off and go to the end. Herunterladen (to download) → Ich lade es herunter. Anrufen (to call) → Ich rufe dich an. Watch for the prefix at the end!","examples":[{"sentence":"Ich lade die App herunter.","translation":"I am downloading the app."},{"sentence":"Ich rufe dich an.","translation":"I will call you."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Handy'' means?","options":["mobile phone","laptop","internet","app"],"correctAnswer":"mobile phone"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I use my laptop.","options":["Ich benutze meinen Laptop.","Ich schicke eine Nachricht.","Das Internet ist gut.","Mein Handy ist neu."],"correctAnswer":"Ich benutze meinen Laptop."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ mein Handy.","options":["lade","schicke","benutze","schaue"],"correctAnswer":"lade"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am sending a message","wordBankItems":["Ich","schicke","eine","Nachricht","."],"correctAnswer":"Ich schicke eine Nachricht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schicken'' means?","options":["to send","to download","to use","to watch"],"correctAnswer":"to send"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 30: Die Natur
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-00000000001e',1,'APPROVED','PUBLISHED',
'{"objectives":["Name natural features","Talk about the outdoors","Use gehen for activities"],"explanation":{"intro":"Germany has beautiful natural landscapes — from the Black Forest to the Alps. Nature vocabulary lets you describe and enjoy the outdoors.","culturalNote":"Wandern (hiking) is extremely popular in Germany. The Black Forest (Schwarzwald) has over 23,000 km of marked trails."},"examples":[{"german":"Wir gehen in den Wald.","english":"We are going into the forest."},{"german":"Der Berg ist hoch.","english":"The mountain is high."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can name natural features and talk about outdoor activities."}}',
'{"items":[{"word":"der Wald","translation":"forest","pronunciation":"dayr VALT","example":"Der Wald ist dunkel."},{"word":"der Berg","translation":"mountain","pronunciation":"dayr BERG","example":"Wir wandern auf den Berg."},{"word":"der See","translation":"lake","pronunciation":"dayr ZAY","example":"Der See ist klar."},{"word":"der Fluss","translation":"river","pronunciation":"dayr FLOOS","example":"Der Fluss fließt schnell."},{"word":"wandern","translation":"to hike","pronunciation":"VAN-dern","example":"Ich wandere gern."},{"word":"das Tal","translation":"valley","pronunciation":"dahs TAHL","example":"Das Tal ist grün."}]}',
'{"title":"In den / auf den — direction with accusative","pattern":"gehen in/auf + accusative (direction)","explanation":"When expressing movement toward something, use accusative. Der Wald (nominative) → in den Wald (accusative, direction). Der Berg → auf den Berg. This contrasts with location: im Wald (dative, location).","examples":[{"sentence":"Ich gehe in den Wald.","translation":"I am going into the forest."},{"sentence":"Wir laufen auf den Berg.","translation":"We are running up the mountain."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der See'' means?","options":["lake","sea","river","forest"],"correctAnswer":"lake"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like hiking.","options":["Ich wandere gern.","Wir gehen in den Wald.","Der Berg ist hoch.","Das Tal ist grün."],"correctAnswer":"Ich wandere gern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir gehen in ___ Wald.","options":["den","dem","der","das"],"correctAnswer":"den"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The river flows fast","wordBankItems":["Der","Fluss","fließt","schnell","."],"correctAnswer":"Der Fluss fließt schnell ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wandern'' means?","options":["to hike","to swim","to run","to climb"],"correctAnswer":"to hike"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 31: Die Post
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-00000000001f',1,'APPROVED','PUBLISHED',
'{"objectives":["Use the post office","Send letters and parcels","Use schicken and senden"],"explanation":{"intro":"Even in the digital age, knowing post office vocabulary is useful for sending packages, paying bills and official correspondence.","culturalNote":"Deutsche Post is the German postal service. Its yellow DHL vans are a common sight. Letters within Germany typically arrive the next day."},"examples":[{"german":"Ich möchte dieses Paket schicken.","english":"I would like to send this parcel."},{"german":"Wie viel kostet eine Briefmarke?","english":"How much does a stamp cost?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can use the post office and send letters and parcels."}}',
'{"items":[{"word":"die Post","translation":"post office / post","pronunciation":"dee POST","example":"Ich gehe zur Post."},{"word":"der Brief","translation":"letter","pronunciation":"dayr BREEF","example":"Ich schreibe einen Brief."},{"word":"das Paket","translation":"parcel","pronunciation":"dahs pah-KET","example":"Das Paket ist schwer."},{"word":"die Briefmarke","translation":"stamp","pronunciation":"dee BREEF-mar-keh","example":"Ich brauche eine Briefmarke."},{"word":"schicken","translation":"to send","pronunciation":"SHIK-en","example":"Ich schicke das Paket."},{"word":"die Adresse","translation":"address","pronunciation":"dee ah-DRES-seh","example":"Was ist deine Adresse?"}]}',
'{"title":"Brauchen — to need","pattern":"ich brauche + accusative noun","explanation":"Brauchen means to need. It takes the accusative case. Ich brauche eine Briefmarke = I need a stamp. Ich brauche einen Umschlag = I need an envelope. Very practical for service encounters.","examples":[{"sentence":"Ich brauche ein Paket.","translation":"I need a parcel."},{"sentence":"Brauchst du Hilfe?","translation":"Do you need help?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Briefmarke'' means?","options":["stamp","letter","parcel","address"],"correctAnswer":"stamp"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like to send this letter.","options":["Ich möchte diesen Brief schicken.","Ich brauche eine Briefmarke.","Das Paket ist schwer.","Ich gehe zur Post."],"correctAnswer":"Ich möchte diesen Brief schicken."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ eine Briefmarke.","options":["brauche","schicke","habe","gehe"],"correctAnswer":"brauche"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What is your address?","wordBankItems":["Was","ist","deine","Adresse","?"],"correctAnswer":"Was ist deine Adresse ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Paket'' means?","options":["parcel","letter","stamp","postbox"],"correctAnswer":"parcel"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 32: Bei der Bank
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000020',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle basic banking tasks","Talk about money","Use abheben and einzahlen"],"explanation":{"intro":"Banking vocabulary is practical for daily life. Whether opening an account or withdrawing cash, these words are essential.","culturalNote":"Cash is still king in Germany — many shops and restaurants do not accept cards. Always carry some Bargeld (cash)!"},"examples":[{"german":"Ich möchte Geld abheben.","english":"I would like to withdraw money."},{"german":"Was ist mein Kontostand?","english":"What is my account balance?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can handle basic banking transactions in German."}}',
'{"items":[{"word":"die Bank","translation":"bank","pronunciation":"dee BANK","example":"Ich gehe zur Bank."},{"word":"das Konto","translation":"account","pronunciation":"dahs KON-toh","example":"Ich habe ein Konto."},{"word":"abheben","translation":"to withdraw","pronunciation":"AP-hay-ben","example":"Ich hebe Geld ab."},{"word":"einzahlen","translation":"to deposit","pronunciation":"YN-tsah-len","example":"Ich zahle Geld ein."},{"word":"der Geldautomat","translation":"ATM/cash machine","pronunciation":"dayr GELT-ow-toh-maht","example":"Wo ist der Geldautomat?"},{"word":"das Bargeld","translation":"cash","pronunciation":"dahs BAR-gelt","example":"Ich zahle mit Bargeld."}]}',
'{"title":"Separable verbs: abheben, einzahlen","pattern":"prefix splits to end: ich hebe ab / ich zahle ein","explanation":"Abheben and einzahlen are separable verbs. The prefix moves to the sentence end. Ich hebe Geld ab (not Ich abhebe Geld). Ich zahle 50 Euro ein. The base verb conjugates normally.","examples":[{"sentence":"Er hebt 200 Euro ab.","translation":"He withdraws 200 euros."},{"sentence":"Ich zahle morgen ein.","translation":"I will deposit tomorrow."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Geldautomat'' means?","options":["ATM","bank","account","cash"],"correctAnswer":"ATM"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like to withdraw money.","options":["Ich möchte Geld abheben.","Ich zahle Geld ein.","Was ist mein Kontostand?","Ich zahle mit Bargeld."],"correctAnswer":"Ich möchte Geld abheben."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich hebe Geld ___.","options":["ab","ein","aus","an"],"correctAnswer":"ab"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Where is the ATM?","wordBankItems":["Wo","ist","der","Geldautomat","?"],"correctAnswer":"Wo ist der Geldautomat ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Bargeld'' means?","options":["cash","card","account","money"],"correctAnswer":"cash"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 33: Beim Arzt
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000021',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe symptoms to a doctor","Make a medical appointment","Use seit for duration of symptoms"],"explanation":{"intro":"Medical vocabulary is important for any stay in a German-speaking country. Be able to describe symptoms clearly.","culturalNote":"In Germany you need a Krankenkassenkarte (health insurance card) to see a doctor. Most doctors have Sprechstunden (consulting hours)."},"examples":[{"german":"Ich habe seit drei Tagen Fieber.","english":"I have had a fever for three days."},{"german":"Ich brauche einen Termin.","english":"I need an appointment."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe symptoms and make a doctor appointment."}}',
'{"items":[{"word":"der Arzt","translation":"doctor (m)","pronunciation":"dayr ARTST","example":"Der Arzt kommt gleich."},{"word":"das Fieber","translation":"fever","pronunciation":"dahs FEE-ber","example":"Ich habe Fieber."},{"word":"der Husten","translation":"cough","pronunciation":"dayr HOO-sten","example":"Ich habe Husten."},{"word":"der Termin","translation":"appointment","pronunciation":"dayr ter-MEEN","example":"Ich brauche einen Termin."},{"word":"das Rezept","translation":"prescription","pronunciation":"dahs reh-TSEPT","example":"Hier ist Ihr Rezept."},{"word":"seit","translation":"since/for (time)","pronunciation":"ZYT","example":"Seit wann bist du krank?"}]}',
'{"title":"Seit + dative — duration up to now","pattern":"seit + time expression (dative) + present tense","explanation":"Seit with present tense expresses an ongoing state. Ich bin seit zwei Tagen krank = I have been sick for two days (and still am). English uses past tense here but German uses present.","examples":[{"sentence":"Ich habe seit gestern Schmerzen.","translation":"I have had pain since yesterday."},{"sentence":"Er hustet seit einer Woche.","translation":"He has been coughing for a week."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Fieber'' means?","options":["fever","cough","pain","appointment"],"correctAnswer":"fever"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need an appointment.","options":["Ich brauche einen Termin.","Ich habe Fieber.","Mir tut der Kopf weh.","Das Rezept ist fertig."],"correctAnswer":"Ich brauche einen Termin."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich habe ___ drei Tagen Husten.","options":["seit","vor","nach","ab"],"correctAnswer":"seit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Here is your prescription","wordBankItems":["Hier","ist","Ihr","Rezept","."],"correctAnswer":"Hier ist Ihr Rezept ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Termin'' means?","options":["appointment","prescription","doctor","hospital"],"correctAnswer":"appointment"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 34: Im Hotel
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000022',1,'APPROVED','PUBLISHED',
'{"objectives":["Check in and out of a hotel","Ask about room facilities","Use reservieren and buchen"],"explanation":{"intro":"Hotel vocabulary is essential for travel. Learn how to check in, ask about facilities, and handle problems.","culturalNote":"Breakfast is often included in German hotel prices. Many hotels have a Frühstücksbuffet (breakfast buffet) included in the rate."},"examples":[{"german":"Ich habe eine Reservierung.","english":"I have a reservation."},{"german":"Wann ist der Check-out?","english":"When is check-out?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can check into a hotel and ask about facilities."}}',
'{"items":[{"word":"das Hotel","translation":"hotel","pronunciation":"dahs hoh-TEL","example":"Das Hotel ist schön."},{"word":"das Zimmer","translation":"room","pronunciation":"dahs TSIM-er","example":"Mein Zimmer ist ruhig."},{"word":"die Reservierung","translation":"reservation","pronunciation":"dee reh-zer-VEER-oong","example":"Ich habe eine Reservierung."},{"word":"der Schlüssel","translation":"key","pronunciation":"dayr SHLÜS-sel","example":"Hier ist Ihr Schlüssel."},{"word":"das Frühstück","translation":"breakfast","pronunciation":"dahs FRÜH-shtük","example":"Ist Frühstück inklusive?"},{"word":"auschecken","translation":"to check out","pronunciation":"OWS-chek-en","example":"Ich möchte auschecken."}]}',
'{"title":"Inklusive / nicht inklusive","pattern":"Ist ... inklusive?","explanation":"Inklusive (included) and nicht inklusive / exklusive (not included) are essential for hotel stays. Ist das Frühstück inklusive? = Is breakfast included? These words are borrowed from Latin and used widely.","examples":[{"sentence":"Ist WLAN inklusive?","translation":"Is WiFi included?"},{"sentence":"Das Frühstück ist nicht inklusive.","translation":"Breakfast is not included."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Schlüssel'' means?","options":["key","room","hotel","reception"],"correctAnswer":"key"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have a reservation.","options":["Ich habe eine Reservierung.","Ich möchte auschecken.","Das Zimmer ist groß.","Ist Frühstück inklusive?"],"correctAnswer":"Ich habe eine Reservierung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ist das Frühstück ___?","options":["inklusive","kostenlos","gut","groß"],"correctAnswer":"inklusive"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Here is your key","wordBankItems":["Hier","ist","Ihr","Schlüssel","."],"correctAnswer":"Hier ist Ihr Schlüssel ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Reservierung'' means?","options":["reservation","room","key","breakfast"],"correctAnswer":"reservation"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 35: Am Flughafen
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000023',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate an airport","Check in for a flight","Understand flight announcements"],"explanation":{"intro":"Airport vocabulary is essential for any international traveller. Learn the key terms you will encounter at a German airport.","culturalNote":"Frankfurt Airport (Flughafen Frankfurt) is the largest in Germany and one of the busiest in Europe. It is a major hub for Lufthansa."},"examples":[{"german":"Wo ist die Gepäckausgabe?","english":"Where is the baggage claim?"},{"german":"Mein Flug hat Verspätung.","english":"My flight is delayed."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate an airport and handle flight check-in."}}',
'{"items":[{"word":"der Flughafen","translation":"airport","pronunciation":"dayr FLOOK-hah-fen","example":"Wir fahren zum Flughafen."},{"word":"das Gate","translation":"gate","pronunciation":"dahs GAYT","example":"Das Gate ist C12."},{"word":"der Koffer","translation":"suitcase","pronunciation":"dayr KOF-er","example":"Mein Koffer ist schwer."},{"word":"die Verspätung","translation":"delay","pronunciation":"dee fer-SHPAY-toong","example":"Der Flug hat Verspätung."},{"word":"der Pass","translation":"passport","pronunciation":"dayr PASS","example":"Zeigen Sie Ihren Pass."},{"word":"der Abflug","translation":"departure","pronunciation":"dayr AP-flook","example":"Der Abflug ist um 10 Uhr."}]}',
'{"title":"Hat Verspätung — expressing delays","pattern":"Der Flug / Zug hat ... Minuten Verspätung","explanation":"Use hat Verspätung to say something is delayed. You can add the amount: Der Zug hat 20 Minuten Verspätung = The train is 20 minutes late. This works for trains, buses, and flights.","examples":[{"sentence":"Mein Zug hat 30 Minuten Verspätung.","translation":"My train is 30 minutes late."},{"sentence":"Hat der Flug Verspätung?","translation":"Is the flight delayed?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Verspätung'' means?","options":["delay","departure","gate","passport"],"correctAnswer":"delay"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My suitcase is heavy.","options":["Mein Koffer ist schwer.","Der Flug hat Verspätung.","Wo ist das Gate?","Zeigen Sie Ihren Pass."],"correctAnswer":"Mein Koffer ist schwer."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Abflug ist ___ 10 Uhr.","options":["um","an","bei","zu"],"correctAnswer":"um"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Where is the gate?","wordBankItems":["Wo","ist","das","Gate","?"],"correctAnswer":"Wo ist das Gate ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Abflug'' means?","options":["departure","arrival","gate","flight"],"correctAnswer":"departure"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 36: Auf dem Markt
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000024',1,'APPROVED','PUBLISHED',
'{"objectives":["Shop at a market","Ask for quantities","Use Ich hätte gern and Ein Kilo"],"explanation":{"intro":"Farmers markets are popular in Germany, especially on Saturday mornings. Knowing market vocabulary helps you buy fresh produce.","culturalNote":"The Viktualienmarkt in Munich is one of the most famous open-air markets in Germany — it has been operating since 1807."},"examples":[{"german":"Ich hätte gern ein Kilo Tomaten.","english":"I would like a kilo of tomatoes."},{"german":"Was kostet das Kilo?","english":"How much is a kilo?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can shop at a market and ask for quantities."}}',
'{"items":[{"word":"der Markt","translation":"market","pronunciation":"dayr MARKT","example":"Samstags gehe ich auf den Markt."},{"word":"das Kilo","translation":"kilogram","pronunciation":"dahs KEE-loh","example":"Ein Kilo Kartoffeln bitte."},{"word":"die Tomate","translation":"tomato","pronunciation":"dee toh-MAH-teh","example":"Die Tomaten sind frisch."},{"word":"frisch","translation":"fresh","pronunciation":"FRISH","example":"Das Obst ist frisch."},{"word":"der Stand","translation":"stall","pronunciation":"dayr SHTANT","example":"Der Gemüsestand ist dort."},{"word":"das Obst","translation":"fruit (collective)","pronunciation":"dahs OHPST","example":"Ich kaufe Obst."}]}',
'{"title":"Quantities: ein Kilo / ein Pfund / 500 Gramm","pattern":"Ich hätte gern + quantity + noun (accusative)","explanation":"At a market use Ich hätte gern + quantity + item. Ein Kilo = 1 kg, ein Pfund = 500g, 100 Gramm = 100g. The noun after a quantity does not always need an article: ein Kilo Tomaten (no article on Tomaten).","examples":[{"sentence":"Ich hätte gern 500 Gramm Käse.","translation":"I would like 500 grams of cheese."},{"sentence":"Zwei Kilo Äpfel bitte.","translation":"Two kilos of apples please."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Frisch'' means?","options":["fresh","cheap","good","new"],"correctAnswer":"fresh"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like a kilo of tomatoes.","options":["Ich hätte gern ein Kilo Tomaten.","Das Obst ist frisch.","Was kostet das Kilo?","Ich kaufe Obst."],"correctAnswer":"Ich hätte gern ein Kilo Tomaten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ein ___ Kartoffeln bitte.","options":["Kilo","Meter","Liter","Stück"],"correctAnswer":"Kilo"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The vegetables are fresh","wordBankItems":["Das","Gemüse","ist","frisch","."],"correctAnswer":"Das Gemüse ist frisch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Obst'' means?","options":["fruit","vegetable","bread","market"],"correctAnswer":"fruit"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 37: In der Apotheke
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000025',1,'APPROVED','PUBLISHED',
'{"objectives":["Buy medicine at a pharmacy","Describe symptoms briefly","Ask for recommendations"],"explanation":{"intro":"German pharmacies (Apotheken) are indicated by a red A sign. Pharmacists (Apotheker) are highly trained and can give medical advice.","culturalNote":"In Germany, many medicines that are over-the-counter elsewhere require a prescription. The pharmacist (Apotheker) is your first point of contact."},"examples":[{"german":"Ich brauche etwas gegen Kopfschmerzen.","english":"I need something for headaches."},{"german":"Haben Sie Hustensaft?","english":"Do you have cough syrup?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can buy medicine at a pharmacy and describe symptoms."}}',
'{"items":[{"word":"die Apotheke","translation":"pharmacy","pronunciation":"dee ah-poh-TAY-keh","example":"Die Apotheke ist geöffnet."},{"word":"das Medikament","translation":"medicine","pronunciation":"dahs meh-dee-kah-MENT","example":"Das Medikament hilft."},{"word":"die Tablette","translation":"tablet/pill","pronunciation":"dee tab-LET-teh","example":"Nehmen Sie zwei Tabletten."},{"word":"gegen","translation":"against/for (ailment)","pronunciation":"GAY-gen","example":"Etwas gegen Schmerzen."},{"word":"der Hustensaft","translation":"cough syrup","pronunciation":"dayr HOO-sten-zaft","example":"Ich brauche Hustensaft."},{"word":"verschreibungspflichtig","translation":"prescription-only","pronunciation":"fer-SHRY-boongs-pflikh-tikh","example":"Das ist verschreibungspflichtig."}]}',
'{"title":"Etwas gegen — something for an ailment","pattern":"Ich brauche etwas gegen + ailment (accusative)","explanation":"Use etwas gegen to ask for a remedy. Etwas gegen Kopfschmerzen = something for headaches; etwas gegen Husten = something for a cough. Gegen always takes accusative.","examples":[{"sentence":"Haben Sie etwas gegen Fieber?","translation":"Do you have something for fever?"},{"sentence":"Ich brauche etwas gegen Übelkeit.","translation":"I need something for nausea."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Tablette'' means?","options":["tablet","syrup","prescription","pharmacy"],"correctAnswer":"tablet"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need something for headaches.","options":["Ich brauche etwas gegen Kopfschmerzen.","Haben Sie Hustensaft?","Das Medikament hilft.","Die Apotheke ist offen."],"correctAnswer":"Ich brauche etwas gegen Kopfschmerzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nehmen Sie zwei ___ täglich.","options":["Tabletten","Flaschen","Päckchen","Löffel"],"correctAnswer":"Tabletten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Do you have cough syrup?","wordBankItems":["Haben","Sie","Hustensaft","?"],"correctAnswer":"Haben Sie Hustensaft ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gegen'' means in medical context?","options":["for/against","with","without","after"],"correctAnswer":"for/against"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 38: In der Bäckerei
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000026',1,'APPROVED','PUBLISHED',
'{"objectives":["Order at a bakery","Name bread and pastry types","Use ein Stück and eine Scheibe"],"explanation":{"intro":"German bakeries (Bäckereien) are world-renowned. Germany has over 300 types of bread! Morning trips to the bakery are a beloved tradition.","culturalNote":"German bread culture (Brotkultur) is so important it was added to UNESCO cultural heritage. Vollkornbrot (wholegrain bread) and Brezel (pretzel) are iconic."},"examples":[{"german":"Ein Vollkornbrot, bitte.","english":"One wholegrain loaf, please."},{"german":"Zwei Brötchen und eine Brezel.","english":"Two rolls and a pretzel."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can order bread and pastries at a German bakery."}}',
'{"items":[{"word":"die Bäckerei","translation":"bakery","pronunciation":"dee BEK-ker-eye","example":"Die Bäckerei öffnet um 6 Uhr."},{"word":"das Brötchen","translation":"bread roll","pronunciation":"dahs BRÜT-khen","example":"Vier Brötchen bitte."},{"word":"die Brezel","translation":"pretzel","pronunciation":"dee BRET-sel","example":"Eine Brezel kostet 1 Euro."},{"word":"das Vollkornbrot","translation":"wholegrain bread","pronunciation":"dahs FOL-korn-broht","example":"Ein Vollkornbrot bitte."},{"word":"frisch gebacken","translation":"freshly baked","pronunciation":"FRISH geh-BAK-en","example":"Das Brot ist frisch gebacken."},{"word":"das Stück","translation":"piece","pronunciation":"dahs SHTÜK","example":"Ein Stück Kuchen bitte."}]}',
'{"title":"Counting with ein/eine/einen for bakery items","pattern":"ein/eine/einen + bakery item (accusative)","explanation":"When ordering one item, use the accusative form: einen for masculine (einen Kuchen), eine for feminine (eine Brezel), ein for neuter (ein Brötchen). For quantities just use the number: zwei Brötchen, drei Brezeln.","examples":[{"sentence":"Ich nehme einen Croissant.","translation":"I will have a croissant."},{"sentence":"Zwei Brötchen und eine Brezel.","translation":"Two rolls and a pretzel."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Brötchen'' means?","options":["bread roll","pretzel","cake","loaf"],"correctAnswer":"bread roll"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The bread is freshly baked.","options":["Das Brot ist frisch gebacken.","Ein Brötchen kostet 50 Cent.","Die Brezel ist gut.","Vier Brötchen bitte."],"correctAnswer":"Das Brot ist frisch gebacken."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ein ___ Kuchen bitte.","options":["Stück","Kilo","Liter","Meter"],"correctAnswer":"Stück"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Two rolls and a pretzel","wordBankItems":["Zwei","Brötchen","und","eine","Brezel","."],"correctAnswer":"Zwei Brötchen und eine Brezel ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Bäckerei'' means?","options":["bakery","pharmacy","supermarket","café"],"correctAnswer":"bakery"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 39: In der Buchhandlung
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000027',1,'APPROVED','PUBLISHED',
'{"objectives":["Find books in a bookshop","Ask for recommendations","Talk about reading preferences"],"explanation":{"intro":"Germany has a rich literary culture. Bookshops (Buchhandlungen) are common and well-stocked. Frankfurt hosts the world famous Buchmesse (book fair) every year.","culturalNote":"The Frankfurt Book Fair (Frankfurter Buchmesse) is the world largest trade fair for books. It takes place every October."},"examples":[{"german":"Haben Sie Bücher auf Englisch?","english":"Do you have books in English?"},{"german":"Ich suche einen Roman von Kafka.","english":"I am looking for a novel by Kafka."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can find books in a bookshop and ask for recommendations."}}',
'{"items":[{"word":"die Buchhandlung","translation":"bookshop","pronunciation":"dee BOOKH-hant-loong","example":"Die Buchhandlung ist groß."},{"word":"der Roman","translation":"novel","pronunciation":"dayr roh-MAHN","example":"Ich lese einen Roman."},{"word":"das Sachbuch","translation":"non-fiction book","pronunciation":"dahs ZAKH-bookh","example":"Ich mag Sachbücher."},{"word":"der Autor","translation":"author","pronunciation":"dayr OW-tor","example":"Wer ist der Autor?"},{"word":"suchen","translation":"to look for","pronunciation":"ZOO-khen","example":"Ich suche ein Buch."},{"word":"empfehlen","translation":"to recommend","pronunciation":"em-PFAY-len","example":"Können Sie etwas empfehlen?"}]}',
'{"title":"Können Sie — can you (polite requests)","pattern":"Können Sie + infinitive?","explanation":"Können Sie is the polite (Sie) form of können (to be able to). Use it for polite requests in shops: Können Sie mir helfen? = Can you help me? Können Sie etwas empfehlen? = Can you recommend something?","examples":[{"sentence":"Können Sie mir helfen?","translation":"Can you help me?"},{"sentence":"Können Sie das einpacken?","translation":"Can you wrap that?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Roman'' means?","options":["novel","biography","textbook","magazine"],"correctAnswer":"novel"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am looking for a book by Goethe.","options":["Ich suche ein Buch von Goethe.","Haben Sie Romane?","Können Sie empfehlen?","Ich lese gern."],"correctAnswer":"Ich suche ein Buch von Goethe."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Können Sie etwas ___?","options":["empfehlen","suchen","lesen","kaufen"],"correctAnswer":"empfehlen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Can you help me?","wordBankItems":["Können","Sie","mir","helfen","?"],"correctAnswer":"Können Sie mir helfen ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Suchen'' means?","options":["to look for","to find","to buy","to read"],"correctAnswer":"to look for"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

-- LESSON 40: Im Fitnessstudio
INSERT INTO cf_lesson_versions (lesson_id, version, content_status, publication_status, content, vocabulary, grammar, exercises, frozen, published_at) VALUES (
'aa000000-0000-0000-0000-000000000028',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about gym activities","Say how long you exercise","Use seit and lang for duration"],"explanation":{"intro":"Gym vocabulary is useful for health and fitness conversations. Germany has a large fitness industry with many Fitnessstudios across the country.","culturalNote":"McFit and Clever Fit are major budget gym chains in Germany. Monthly memberships typically cost €20-25."},"examples":[{"german":"Ich trainiere dreimal pro Woche.","english":"I train three times a week."},{"german":"Ich mache seit einem Jahr Krafttraining.","english":"I have been doing weight training for a year."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about gym activities and my fitness routine."}}',
'{"items":[{"word":"das Fitnessstudio","translation":"gym","pronunciation":"dahs FIT-nes-shtoo-dee-oh","example":"Ich gehe ins Fitnessstudio."},{"word":"trainieren","translation":"to train/work out","pronunciation":"trai-NEER-en","example":"Ich trainiere jeden Tag."},{"word":"das Krafttraining","translation":"weight training","pronunciation":"dahs KRAFT-trai-ning","example":"Krafttraining macht stark."},{"word":"die Hantel","translation":"dumbbell","pronunciation":"dee HAN-tel","example":"Ich hebe Hanteln."},{"word":"der Muskel","translation":"muscle","pronunciation":"dayr MOOS-kel","example":"Meine Muskeln sind müde."},{"word":"aufwärmen","translation":"to warm up","pronunciation":"OWF-ver-men","example":"Ich wärme mich auf."}]}',
'{"title":"Dreimal pro Woche — frequency expressions","pattern":"number + mal + pro + time period","explanation":"To say how often you do something, use: einmal (once), zweimal (twice), dreimal (three times) + pro Woche/Monat/Jahr. Dreimal pro Woche trainieren = to train three times a week.","examples":[{"sentence":"Ich trainiere fünfmal pro Woche.","translation":"I train five times a week."},{"sentence":"Einmal pro Tag aufwärmen.","translation":"Warm up once a day."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Trainieren'' means?","options":["to train","to rest","to eat","to sleep"],"correctAnswer":"to train"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I go to the gym.","options":["Ich gehe ins Fitnessstudio.","Ich trainiere gern.","Die Hanteln sind schwer.","Ich wärme mich auf."],"correctAnswer":"Ich gehe ins Fitnessstudio."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich trainiere dreimal ___ Woche.","options":["pro","per","im","am"],"correctAnswer":"pro"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My muscles are tired","wordBankItems":["Meine","Muskeln","sind","müde","."],"correctAnswer":"Meine Muskeln sind müde ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Hantel'' means?","options":["dumbbell","muscle","gym","training"],"correctAnswer":"dumbbell"}]}'::jsonb,
true, NOW()) ON CONFLICT (lesson_id, version) DO NOTHING;

